import { createCapabilityRegistry } from '../../../lib/low-code/runtime-core/capabilities'
import type {
    HostAdapter,
    Json,
    PagePackage,
    Values
} from '../../../lib/low-code/schema'
import type { NodeFlowActionBody } from '../mofangsdk/core/node-flow-types'
import {
    createWorkflowSdkService,
    WORKFLOW_SDK_METHODS
} from '../mofangsdk/lowcode'
import { hostLifecycle } from './lifecycle'
import { runNodeAction } from './node-action'
import { subscribeNodeFlowContext } from './node-flow-context'
import { jsonValues, resolveSettingsFormId, settingsFields } from './settings'
import type { PuckPanelHostProps } from './types'

const sdkIds = new WeakMap<object, number>()
let nextSdkId = 0

/** 完整公开 SDK 服务与可视化单次调用共用同一个受宿主约束的门面。 */
export function createPuckPanelHost(props: PuckPanelHostProps): HostAdapter {
    const { target, sdk, settings, surface } = props
    const page = props.lowcode.config as unknown as PagePackage
    const formId = settings ? resolveSettingsFormId(page) : 'main'
    const readOnly = Boolean(settings?.readOnly || target.view === 'history')
    if (sdk && !sdkIds.has(sdk)) sdkIds.set(sdk, ++nextSdkId)
    const instanceKey = JSON.stringify([
        surface,
        target,
        props.lowcode.config,
        sdk ? sdkIds.get(sdk) : null
    ])
    const nodeRunId = () => {
        if (!target.nodeRunId) throw new Error('当前面板缺少节点运行 ID')
        return target.nodeRunId
    }
    const service = sdk
        ? createWorkflowSdkService({
              sdk,
              target,
              readOnly: settings?.readOnly
          })
        : undefined
    const capabilities = createCapabilityRegistry()
    const lifecycle = hostLifecycle(service ?? props, instanceKey)
    const { pending } = lifecycle
    const call: HostAdapter['call'] = async (id, input, signal) => {
        signal.throwIfAborted()
        if (id === 'workflow.settings.resetField') {
            if (readOnly) throw new Error('当前配置为只读')
            const fields = settingsFields(page, formId)
            const selected =
                typeof input.fieldId === 'string'
                    ? fields.find((field) => field.id === input.fieldId)
                    : undefined
            const name = selected?.name ?? input.name
            if (
                !settings ||
                (input.fieldId !== undefined && !selected) ||
                typeof name !== 'string' ||
                !fields.some((field) => field.name === name)
            )
                throw new Error('重置字段不属于当前配置表单')
            settings.onFieldChange?.(name, undefined)
            return null
        }
        if (!service) throw new Error('当前面板缺少工作流 SDK')
        if (id === 'workflow.nodeAction.run') {
            if (readOnly) throw new Error('当前面板为只读，不能执行节点动作')
            const controller = new AbortController()
            const abort = () => controller.abort(signal.reason)
            signal.addEventListener('abort', abort, { once: true })
            pending.add(controller)
            try {
                return jsonValues(
                    await runNodeAction(
                        service.value.nodeFlow,
                        {
                            runId: target.runId ?? '',
                            nodeInstanceId: target.nodeInstanceId ?? ''
                        },
                        input as unknown as NodeFlowActionBody,
                        controller.signal
                    )
                )
            } finally {
                signal.removeEventListener('abort', abort)
                pending.delete(controller)
            }
        }
        const method = WORKFLOW_SDK_METHODS.find(
            (item) => `sdk.${item.path}` === id
        )
        if (!method) throw new Error(`Puck 面板不支持宿主动作：${id}`)
        if (method.kind === 'subscribe' || method.kind === 'resource')
            throw new Error('订阅和资源方法请在事件 JS 中调用并释放订阅')
        let args: unknown[]
        if (Object.prototype.hasOwnProperty.call(input, 'args')) {
            if (!Array.isArray(input.args))
                throw new Error('SDK 动作参数 args 必须是数组')
            args = input.args
        } else if (id === 'sdk.context.getCurrentContext') args = [target]
        else if (id === 'sdk.nodes.getRun' || id === 'sdk.outputs.get')
            args = [nodeRunId()]
        else if (
            !method.parameters.length ||
            method.parameters.every((p) => p.optional)
        )
            args = []
        else throw new Error('SDK 动作需要显式的 args 参数数组')
        const parts = method.path.split('.')
        let owner: unknown = service.value
        for (const part of parts.slice(0, -1))
            owner = (owner as Record<string, unknown>)[part]
        const fn = (owner as Record<string, (...args: unknown[]) => unknown>)[
            parts.at(-1)!
        ]
        const result = await Reflect.apply(fn, owner, args)
        // SDK 不保证取消底层请求；迟到结果仍不能返回旧页面。
        signal.throwIfAborted()
        return JSON.parse(JSON.stringify(result ?? null)) as Json
    }
    for (const method of WORKFLOW_SDK_METHODS) {
        if (method.kind === 'subscribe' || method.kind === 'resource') continue
        const id = `sdk.${method.path}`
        capabilities.register(id, {
            kind: 'action',
            label: method.label,
            input: method.signature,
            result: method.description,
            handler: (input) =>
                call(id, (input ?? {}) as Values, new AbortController().signal)
        })
    }
    for (const id of [
        'workflow.settings.resetField',
        'workflow.nodeAction.run'
    ])
        capabilities.register(id, {
            kind: 'action',
            completion: 'completed',
            handler: (input) =>
                call(id, (input ?? {}) as Values, new AbortController().signal)
        })
    const context: Values = {
        target: target as unknown as Json,
        nodeView: (props.nodeView as unknown as Json) ?? null,
        nodeOutput: (props.nodeOutput as unknown as Json) ?? null,
        nodeFlow: null,
        settings: jsonValues(settings?.values ?? {}),
        settingsFormId: formId,
        readOnly
    }
    return {
        instanceKey,
        context,
        subscribeContext: (listener) => {
            const dispose = lifecycle.retain()
            if (!service || !target.runId || !target.nodeInstanceId)
                return dispose
            const release = subscribeNodeFlowContext(
                service.value,
                {
                    runId: target.runId,
                    nodeInstanceId: target.nodeInstanceId,
                    view: target.view === 'history' ? 'history' : 'current'
                },
                context,
                listener
            )
            return () => {
                release()
                dispose()
            }
        },
        initialValues: settings
            ? { [formId]: jsonValues(settings.values) }
            : undefined,
        services: service ? { workflowSdk: service } : {},
        capabilities,
        actionOutputKeys: Object.fromEntries(
            WORKFLOW_SDK_METHODS.filter(
                (method) => method.effect === 'write'
            ).map((method) => [
                `sdk.${method.path}`,
                ['nodeView', 'nodeOutput']
            ])
        ),
        call
    }
}
