import type {
    NodeActionResult,
    NodeFlowActionBody,
    NodeFlowActionReceipt,
    NodeFlowAPI,
    NodeFlowTarget
} from '../mofangsdk/core/node-flow-types'
import { isTerminalNodeAction } from '../mofangsdk/core/node-flow-types'
import { abortableResult } from './cancellation'

const failure = (message: string, code: string, detail?: unknown) =>
    Object.assign(new Error(message), { code, retryable: false, detail })

/** 便捷动作只在 applied 后 resolve；原 sdk.nodeFlow.action 仍返回 accepted。 */
export async function runNodeAction(
    api: NodeFlowAPI,
    target: NodeFlowTarget,
    body: NodeFlowActionBody,
    signal: AbortSignal,
    timeoutMs = 30000
): Promise<NodeActionResult> {
    signal.throwIfAborted()
    if (
        !target.runId ||
        !target.nodeInstanceId ||
        body.runId !== target.runId ||
        body.nodeInstanceId !== target.nodeInstanceId
    )
        throw failure('动作目标与当前节点不一致', 'target_mismatch')
    if (
        typeof body.name !== 'string' ||
        !body.name.trim() ||
        typeof body.expectedSessionRevision !== 'string' ||
        !/^[1-9]\d*$/.test(body.expectedSessionRevision) ||
        !body.payload ||
        typeof body.payload !== 'object' ||
        Array.isArray(body.payload) ||
        !Array.isArray(body.candidates)
    )
        throw failure('节点动作参数无效', 'input_invalid')
    const view = await abortableResult(api.get(target), signal)
    signal.throwIfAborted()
    if (
        view.runId !== target.runId ||
        view.nodeInstanceId !== target.nodeInstanceId
    )
        throw failure('节点快照与当前目标不一致', 'target_mismatch')
    const projection = view.composition.projection
    if (projection.status !== 'ready')
        throw failure('节点投影尚未就绪', 'projection_unavailable')
    const action = projection.actions.find((item) => item.name === body.name)
    if (!view.permissions.canAct || !action || !action.availability.enabled)
        throw failure(
            action && !action.availability.enabled
                ? action.availability.reason
                : '当前节点动作不可用',
            'action_unavailable'
        )
    if (
        view.composition.snapshot.sessionRevision !==
        body.expectedSessionRevision
    )
        throw failure('节点修订已变化，请重新核对', 'revision_conflict')
    const ids = new Set<string>()
    for (const candidate of body.candidates) {
        if (
            !candidate ||
            typeof candidate.id !== 'string' ||
            !candidate.id ||
            typeof candidate.expectedRevision !== 'string' ||
            !/^[1-9]\d*$/.test(candidate.expectedRevision) ||
            ids.has(candidate.id)
        )
            throw failure('候选项身份或修订无效', 'input_invalid')
        ids.add(candidate.id)
        const current = view.nodeOutput.items.find(
            (item) => item.id === candidate.id
        )
        if (current && current.revision !== candidate.expectedRevision)
            throw failure('候选项修订已变化，请重新核对', 'revision_conflict')
    }
    // payloadSchema 的完整语义由 SDK/服务端合同验证；不实现弱化版 JSON Schema。
    let receipt: NodeFlowActionReceipt
    try {
        receipt = await abortableResult(api.action(body), signal)
    } catch (error) {
        signal.throwIfAborted()
        if (
            error &&
            typeof error === 'object' &&
            'kind' in error &&
            ['rejected', 'conflict'].includes(String(error.kind))
        )
            throw error
        throw failure(
            '动作提交结果未知，请核对动作记录，不能自动重发',
            'needs_review',
            error
        )
    }
    signal.throwIfAborted()
    return new Promise((resolve, reject) => {
        let settled = false
        let release: (() => void) | undefined
        let timer: ReturnType<typeof setTimeout> | undefined
        const finish = (result?: NodeActionResult, error?: unknown) => {
            if (settled) return
            settled = true
            release?.()
            clearTimeout(timer)
            signal.removeEventListener('abort', abort)
            if (error) reject(error)
            else resolve(result!)
        }
        const abort = () =>
            finish(
                undefined,
                signal.reason ??
                    new DOMException('动作等待已取消', 'AbortError')
            )
        const unknown = (cause?: unknown) =>
            finish(
                undefined,
                failure(
                    '动作结果未知，请核对原动作，不能自动重发',
                    'needs_review',
                    { receipt, cause }
                )
            )
        signal.addEventListener('abort', abort, { once: true })
        if (signal.aborted) {
            abort()
            return
        }
        try {
            const store = api.watchActionResult({
                ...target,
                eventId: receipt.eventId
            })
            const update = () => {
                const state = store.getSnapshot()
                if (state.error) {
                    unknown(state.error)
                    return
                }
                const result = state.data
                if (!result || !isTerminalNodeAction(result.status)) return
                if (result.eventId !== receipt.eventId) {
                    unknown('动作回执身份不匹配')
                    return
                }
                if (result.status === 'applied') finish(result)
                else
                    finish(
                        undefined,
                        failure(
                            result.error?.message ?? `动作${result.status}`,
                            result.status,
                            result
                        )
                    )
            }
            release = store.subscribe(update)
            if (settled) release()
            else {
                timer = setTimeout(() => unknown('等待超时'), timeoutMs)
                update()
            }
        } catch (error) {
            unknown(error)
        }
    })
}
