import { selectRuntimeServices } from '../runtime-services'
import type { JsonValue, ScriptCapability } from './contracts'

export type CapabilityKind = 'form' | 'dataSource' | 'action' | 'dialog'
export type CapabilityMetadata = {
    label?: string
    input?: string
    result?: string
    completion?: 'completed' | 'submitted' | 'closed'
}
export type CapabilityEntry = CapabilityMetadata & {
    kind: CapabilityKind
    handler: (...args: JsonValue[]) => Promise<JsonValue> | JsonValue
}
export type CapabilityRegistry = {
    invoke: ScriptCapability
    has: (method: string) => boolean
    list: () => ({ name: string; kind: CapabilityKind } & CapabilityMetadata)[]
    register: (method: string, entry: CapabilityEntry) => void
    remove: (method: string) => boolean
}
const checkName = (method: string) => {
    if (
        !method ||
        method
            .split('.')
            .some(
                (part) =>
                    !part ||
                    ['__proto__', 'constructor', 'prototype'].includes(part)
            )
    )
        throw new Error('能力名称无效')
}
function checkJson(value: unknown, limit: number) {
    let nodes = 0
    const seen = new Set<object>()
    const visit = (item: unknown, depth: number) => {
        if (++nodes > 10000 || depth > 32) throw new Error('脚本数据结构超限')
        if (
            item === null ||
            typeof item === 'string' ||
            typeof item === 'boolean'
        )
            return
        if (typeof item === 'number' && Number.isFinite(item)) return
        if (typeof item !== 'object' || !item || seen.has(item))
            throw new Error('脚本参数和结果必须是 JSON 数据')
        seen.add(item)
        for (const [key, child] of Object.entries(item)) {
            if (!safeKey(key)) throw new Error('脚本参数含无效属性')
            if (child !== undefined) visit(child, depth + 1)
        }
        seen.delete(item)
    }
    visit(value, 0)
    if (JSON.stringify(value).length > limit)
        throw new Error('脚本参数或结果大小超限')
}
function checkDeclaration(
    value: unknown,
    paths: string[] | undefined,
    label: string
) {
    if (!paths?.length) return
    if (!isObject(value)) throw new Error(`脚本${label}声明要求对象`)
    for (const path of paths)
        if (
            !path.split('.').every(safeKey) ||
            resolvePath(value, path.split('.')) === undefined
        )
            throw new Error(`脚本${label}缺少声明路径：${path}`)
}
function checkBuiltinArguments(method: string, args: JsonValue[]) {
    if (['form.getValues', 'dialogs.close'].includes(method)) {
        if (args.length) throw new Error(`脚本能力参数无效：${method}`)
    } else if (method === 'form.patch') {
        if (args.length !== 1 || !isObject(args[0]))
            throw new Error('字段补丁必须是对象')
    } else if (
        ['dataSources.call', 'actions.run', 'dialogs.open'].includes(method)
    ) {
        if (
            args.length < 1 ||
            args.length > 2 ||
            typeof args[0] !== 'string' ||
            !safeKey(args[0]) ||
            (args.length === 2 && !isObject(args[1]))
        )
            throw new Error(`脚本能力参数无效：${method}`)
    }
}
/** 能力注册由宿主持有。页面仅保存依赖名称，不能注入处理函数。 */
export function createCapabilityRegistry(
    entries: Record<string, CapabilityEntry> = {}
): CapabilityRegistry {
    const allowed = new Map<string, CapabilityEntry>()
    const register = (method: string, entry: CapabilityEntry) => {
        checkName(method)
        if (
            !['form', 'dataSource', 'action', 'dialog'].includes(entry.kind) ||
            typeof entry.handler !== 'function'
        )
            throw new Error('能力登记无效')
        allowed.set(method, entry)
    }
    Object.entries(entries).forEach(([method, entry]) =>
        register(method, entry)
    )
    const invoke: ScriptCapability = async (method, args) => {
        const entry = allowed.get(method)
        if (!entry) throw new Error(`脚本能力未授权：${method}`)
        if (!Array.isArray(args) || args.length > 16)
            throw new Error('脚本参数数量超限')
        checkJson(args, 65536)
        const result = await entry.handler(...clone(args))
        checkJson(result, 65536)
        return clone(result)
    }
    return {
        invoke,
        has: (method) => allowed.has(method),
        list: () =>
            [...allowed].map(([name, entry]) => ({
                name,
                kind: entry.kind,
                ...(entry.label ? { label: entry.label } : {}),
                ...(entry.input ? { input: entry.input } : {}),
                ...(entry.result ? { result: entry.result } : {}),
                ...(entry.completion ? { completion: entry.completion } : {})
            })),
        register,
        remove: (method) => allowed.delete(method)
    }
}

import type { RuntimeDefinition, RuntimeSnapshot } from './contracts'
import type { RuntimeOptions } from './runtime'
import {
    abortable,
    clone,
    isObject,
    resolvePath,
    safeKey,
    StaleExecutionError,
    uniqueId
} from './values'

export type ScriptExecutionJournal = { writes: Map<string, JsonValue> }

type ScriptServices = {
    definition: RuntimeDefinition
    options: RuntimeOptions
    controllers: Map<string, AbortController>
    ensure: () => void
    getSnapshot: () => RuntimeSnapshot
    getEpoch: () => number
    getActionVersion: (id: string) => string
    setField: (id: string, value: JsonValue) => void
    openDialog: (id: string, input: Record<string, unknown>) => void
    closeDialog: (force?: boolean) => boolean
    loadSource: (
        id: string,
        params?: Record<string, unknown>,
        current?: RuntimeSnapshot,
        signal?: AbortSignal,
        onMutation?: (phase: 'before' | 'after') => void
    ) => Promise<JsonValue | undefined>
}

/** Script execution extracted without changing guards or capability behavior. */
export function createScriptExecutor(services: ScriptServices) {
    const {
        definition,
        options,
        controllers,
        ensure,
        setField,
        openDialog,
        closeDialog,
        loadSource
    } = services
    const executeScript = async (
        scriptId: string,
        input: unknown,
        current = services.getSnapshot(),
        onMutation: () => void = () => {},
        parentSignal?: AbortSignal,
        journal?: ScriptExecutionJournal
    ): Promise<JsonValue> => {
        ensure()
        const script = definition.scripts.find((s) => s.id === scriptId)
        if (!script) throw new Error(`未知脚本：${scriptId}`)
        if (!options.runScript) throw new Error('脚本执行器未接入')
        const controller = new AbortController(),
            runId = uniqueId()
        const retainedKey = `script-retained:${scriptId}:${String(current.dialog.instanceId ?? '')}`
        if (script.type === 'event') {
            controllers.get(retainedKey)?.abort()
            controllers.set(retainedKey, controller)
        }
        let retained = false
        let returned = false
        let retainedDisposer: (() => void) | undefined
        let expectedEpoch = services.getEpoch(),
            expectedDialog = services.getSnapshot().dialog.instanceId,
            calls = 0,
            callWindow = Date.now(),
            timedOut = false
        const timeout = setTimeout(
            () => {
                timedOut = true
                controller.abort()
            },
            Math.min(script.timeoutMs ?? 3000, 30000)
        )
        controllers.set(runId, controller)
        const abortParent = () => controller.abort()
        parentSignal?.addEventListener('abort', abortParent, { once: true })
        if (parentSignal?.aborted) controller.abort()
        const guard = () => {
            ensure()
            if (timedOut) throw new Error('脚本执行超时')
            if (controller.signal.aborted) {
                if (controller.signal.reason instanceof StaleExecutionError)
                    throw controller.signal.reason
                throw new StaleExecutionError('脚本已停止')
            }
            if (
                (!returned && services.getEpoch() !== expectedEpoch) ||
                services.getSnapshot().dialog.instanceId !== expectedDialog
            )
                throw new StaleExecutionError(
                    '输入或弹框已变化，拒绝旧脚本结果'
                )
        }
        const mutated = () => {
            expectedEpoch = services.getEpoch()
            expectedDialog = services.getSnapshot().dialog.instanceId
            onMutation()
        }
        const requireDependency = (name: string) => {
            if (!script.dependencies?.includes(name))
                throw new Error(`脚本未声明依赖 ${name}`)
        }
        const writeCounts = new Map<string, number>()
        const registry = createCapabilityRegistry({
            'form.getValues': {
                kind: 'form',
                handler: () => {
                    const formId = current.scope?.formId ?? 'main'
                    requireDependency(`form:${formId}`)
                    return clone(services.getSnapshot().forms?.[formId] ?? {})
                }
            },
            'form.patch': {
                kind: 'form',
                handler: (patch) => {
                    requireDependency(`form:${current.scope?.formId ?? 'main'}`)
                    if (!isObject(patch)) throw new Error('字段补丁必须是对象')
                    const entries = Object.entries(patch).map(
                        ([name, value]) => {
                            const id = Object.keys(
                                definition.fields ?? {}
                            ).find((id) => {
                                const f = definition.fields![id]
                                return (
                                    (f.name ?? id) === name &&
                                    (f.formId ?? 'main') ===
                                        (current.scope?.formId ?? 'main')
                                )
                            })
                            if (!id)
                                throw new Error(`当前表单未声明字段：${name}`)
                            return [id, value] as const
                        }
                    )
                    entries.forEach(([id, value]) =>
                        setField(id, value as JsonValue)
                    )
                    mutated()
                    return null
                }
            },
            'dataSources.call': {
                kind: 'dataSource',
                handler: async (id, params) => {
                    requireDependency(`source:${String(id)}`)
                    return (
                        (await loadSource(
                            String(id),
                            isObject(params) ? params : {},
                            {
                                ...services.getSnapshot(),
                                scope: current.scope,
                                row: current.row
                            },
                            controller.signal,
                            (phase) => {
                                if (phase === 'before') guard()
                                else mutated()
                            }
                        )) ?? null
                    )
                }
            },
            'actions.run': {
                kind: 'action',
                handler: async (id, input) => {
                    requireDependency(`action:${String(id)}`)
                    if (!options.action)
                        throw new Error(`宿主动作未接入：${String(id)}`)
                    return options.action(
                        String(id),
                        isObject(input) ? input : {},
                        controller.signal
                    )
                }
            },
            'dialogs.open': {
                kind: 'dialog',
                handler: (id, input) => {
                    requireDependency(`dialog:${String(id)}`)
                    openDialog(String(id), isObject(input) ? input : {})
                    mutated()
                    return null
                }
            },
            'dialogs.close': {
                kind: 'dialog',
                handler: () => {
                    requireDependency(
                        `dialog:${String(services.getSnapshot().dialog.targetId)}`
                    )
                    closeDialog(true)
                    mutated()
                    return null
                }
            }
        })
        try {
            guard()
            checkJson(input, 262144)
            checkDeclaration(input, script.input, '输入')
            const run = options.runScript(
                script,
                clone(input),
                controller.signal,
                async (method, args) => {
                    guard()
                    if (returned && Date.now() - callWindow >= 1000) {
                        calls = 0
                        callWindow = Date.now()
                    }
                    if (++calls > 100) throw new Error('脚本能力调用次数超限')
                    if (script.type !== 'event')
                        throw new Error('纯脚本不能调用宿主能力')
                    checkBuiltinArguments(method, args)
                    const write =
                        method === 'actions.run' ||
                        (method === 'dataSources.call' &&
                            definition.sources.some(
                                (source) =>
                                    source.id === args[0] &&
                                    source.operation === 'mutation'
                            )) ||
                        (!registry.has(method) &&
                            options.capabilities
                                ?.list()
                                .some(
                                    (entry) =>
                                        entry.name === method &&
                                        entry.kind === 'action'
                                ))
                    if (method === 'actions.run')
                        requireDependency(`action:${String(args[0])}`)
                    if (method === 'dataSources.call')
                        requireDependency(`source:${String(args[0])}`)
                    if (!registry.has(method)) {
                        requireDependency(`capability:${method}`)
                        if (!options.capabilities?.has(method))
                            throw new Error(`脚本能力未授权：${method}`)
                    }
                    const signature = JSON.stringify([method, args])
                    const occurrence = (writeCounts.get(signature) ?? 0) + 1
                    if (write && !returned)
                        writeCounts.set(signature, occurrence)
                    const writeKey = `${signature}:${occurrence}`
                    if (!returned && write && journal?.writes.has(writeKey))
                        return clone(journal.writes.get(writeKey)!)
                    const actionId =
                        method === 'actions.run'
                            ? String(args[0])
                            : !registry.has(method)
                              ? method
                              : undefined
                    const actionVersion = actionId
                        ? services.getActionVersion(actionId)
                        : undefined
                    const checkAction = () => {
                        if (
                            actionId &&
                            services.getActionVersion(actionId) !==
                                actionVersion
                        ) {
                            const error = new StaleExecutionError(
                                '输入已变化，拒绝旧脚本结果'
                            )
                            controller.abort(error)
                            throw error
                        }
                        if (actionId) mutated()
                    }
                    let result: JsonValue
                    try {
                        if (registry.has(method))
                            result = await registry.invoke(method, args)
                        else {
                            requireDependency(`capability:${method}`)
                            if (!options.capabilities?.has(method))
                                throw new Error(`脚本能力未授权：${method}`)
                            result = await options.capabilities.invoke(
                                method,
                                args
                            )
                        }
                        checkAction()
                    } catch (error) {
                        checkAction()
                        throw error
                    }
                    guard()
                    if (!returned && write)
                        journal?.writes.set(writeKey, clone(result))
                    return result
                },
                {
                    services: selectRuntimeServices(script, options.services),
                    onRetain: (dispose) => {
                        retained = true
                        retainedDisposer = dispose
                    },
                    onError: (error) => {
                        if (!controller.signal.aborted) {
                            options.onLog?.({
                                instanceId: runId,
                                batchId: '',
                                kind: 'script',
                                id: scriptId,
                                status: 'error',
                                time: Date.now(),
                                detail: error.message
                            })
                            controller.abort()
                        }
                    },
                    invokeService: async (name, method, args, invoke) => {
                        guard()
                        const signature = JSON.stringify([
                            'service',
                            name,
                            method.path,
                            args
                        ])
                        const write =
                            method.kind === 'async' && method.effect === 'write'
                        const occurrence = (writeCounts.get(signature) ?? 0) + 1
                        if (write && !returned)
                            writeCounts.set(signature, occurrence)
                        const writeKey = `${signature}:${occurrence}`
                        if (
                            !returned &&
                            write &&
                            journal?.writes.has(writeKey)
                        ) {
                            const receipt = journal.writes.get(writeKey) as {
                                value: JsonValue
                                isUndefined: boolean
                            }
                            return receipt.isUndefined
                                ? undefined
                                : clone(receipt.value)
                        }
                        const actionId = `${options.services?.[name]?.actionPrefix ?? `${name}.`}${method.path}`
                        const actionVersion =
                            services.getActionVersion(actionId)
                        try {
                            const result = await invoke()
                            if (
                                services.getActionVersion(actionId) !==
                                actionVersion
                            ) {
                                controller.abort(
                                    new StaleExecutionError(
                                        '输入已变化，拒绝旧脚本结果'
                                    )
                                )
                                throw new StaleExecutionError(
                                    '输入已变化，拒绝旧脚本结果'
                                )
                            }
                            mutated()
                            guard()
                            if (!returned && write && journal) {
                                checkJson(result ?? null, 1048576)
                                journal.writes.set(writeKey, {
                                    value: clone(result ?? null) as JsonValue,
                                    isUndefined: result === undefined
                                })
                            }
                            return result
                        } catch (error) {
                            if (
                                services.getActionVersion(actionId) !==
                                actionVersion
                            ) {
                                controller.abort(
                                    new StaleExecutionError(
                                        '输入已变化，拒绝旧脚本结果'
                                    )
                                )
                                throw new StaleExecutionError(
                                    '输入已变化，拒绝旧脚本结果'
                                )
                            }
                            throw error
                        } finally {
                            if (
                                !controller.signal.aborted &&
                                services.getActionVersion(actionId) ===
                                    actionVersion
                            )
                                mutated()
                        }
                    }
                }
            )
            const result = await abortable(run, controller.signal, '脚本已停止')
            guard()
            checkJson(result, 262144)
            checkDeclaration(result, script.output, '输出')
            returned = true
            calls = 0
            callWindow = Date.now()
            return clone(result)
        } catch (error) {
            guard()
            throw error
        } finally {
            clearTimeout(timeout)
            controllers.delete(runId)
            if (retained && returned && !controller.signal.aborted) {
                controllers.set(retainedKey, controller)
                controller.signal.addEventListener(
                    'abort',
                    () => {
                        retainedDisposer?.()
                        parentSignal?.removeEventListener('abort', abortParent)
                        if (controllers.get(retainedKey) === controller)
                            controllers.delete(retainedKey)
                    },
                    { once: true }
                )
            } else {
                retainedDisposer?.()
                if (controllers.get(retainedKey) === controller)
                    controllers.delete(retainedKey)
                parentSignal?.removeEventListener('abort', abortParent)
            }
        }
    }
    return executeScript
}
