import type { Json, Values } from '../../../lib/low-code/schema'
import type { NodeFlowQuery } from '../mofangsdk/core/node-flow-types'
import type { MofangSDK } from '../mofangsdk/core/runtime-types'
import { jsonValues } from './settings'

/** 资源缓存和实时订阅完全由公开 SDK 持有；释放最后一个订阅即停止监听。 */
export function createNodeFlowContextStore(
    sdk: MofangSDK,
    target: NodeFlowQuery
) {
    return sdk.nodeFlow.watch(target)
}

export function subscribeNodeFlowContext(
    sdk: MofangSDK,
    target: NodeFlowQuery,
    context: Values,
    listener: () => void
) {
    const store = createNodeFlowContextStore(sdk, target)
    const update = () => {
        const state = store.getSnapshot()
        context.nodeFlow = jsonValues({
            ...state,
            error: state.error
                ? {
                      ...state.error,
                      message: state.error.message,
                      name: state.error.name
                  }
                : null
        })
        context.nodeView =
            state.data?.composition.projection.status === 'ready'
                ? (state.data.composition.projection.nodeView as Json)
                : null
        context.nodeOutput = (state.data?.nodeOutput as unknown as Json) ?? null
        listener()
    }
    const release = store.subscribe(update)
    update()
    return release
}
