import type { ID, Revision } from './json-types'
import type { MutationReceipt } from './mutation-types'

/**
 * 失败分类只影响调用方怎么处理，不改变服务端语义：
 * - transport：请求可能根本没到服务端，结果未知，可以用原键重发；
 * - conflict：服务端已有更新的修订，重发没用，必须先重读；
 * - rejected：服务端明确拒绝，改数据才有意义；
 * - protocol：其他服务端错误；
 * - unknown：SDK 内部无法归类的异常。
 */
export type MofangSDKErrorKind =
    | 'transport'
    | 'conflict'
    | 'rejected'
    | 'protocol'
    | 'unknown'

/** 服务端机器错误码里表示"本地副本过期"的那些。 */
const CONFLICT_CODES: ReadonlySet<string> = new Set([
    'revision_conflict',
    'config_revision_conflict',
    'panel_revision_conflict',
    'domain_revision_conflict',
    'input_context_stale'
])

/** 服务端明确拒绝、重发无意义的那些。 */
const REJECTED_CODES: ReadonlySet<string> = new Set([
    'domain_reference_denied',
    'result_evidence_invalid',
    'input_invalid',
    'input_missing',
    'unsupported_sdk_version',
    'run_closed',
    'workflow_active',
    'workflow_definition_locked',
    'retry_target_invalid',
    'retry_budget_exhausted'
])

const TRANSPORT_CODE = 'transport_failed'
const UNKNOWN_CODE = 'unknown_error'

export type MofangSDKErrorFields = Readonly<{
    kind: MofangSDKErrorKind
    code: string
    /** 只读请求重试是否可能成功。 */
    retryable: boolean
    requestId?: ID
    resourceRevision?: Revision
    httpStatus?: number
}>

export class MofangSDKError extends Error {
    readonly kind: MofangSDKErrorKind
    readonly code: string
    readonly retryable: boolean
    readonly requestId?: ID
    readonly httpStatus?: number
    readonly resourceRevision?: Revision

    constructor(message: string, fields: MofangSDKErrorFields) {
        super(message)
        this.name = 'MofangSDKError'
        this.kind = fields.kind
        this.code = fields.code
        this.retryable = fields.retryable
        this.requestId = fields.requestId
        this.resourceRevision = fields.resourceRevision
        this.httpStatus = fields.httpStatus
    }
}

/**
 * 把服务端机器错误码归到失败分类。
 *
 * 传输实现也用它：业务失败通常以 HTTP 错误信封回来（不是失败回执），
 * 分类口径必须只有一处，否则同一错误走两条路会得到不同 kind。
 */
export function classifyErrorCode(code: string): MofangSDKErrorKind {
    if (CONFLICT_CODES.has(code)) return 'conflict'
    if (REJECTED_CODES.has(code)) return 'rejected'
    return 'protocol'
}

/** 服务端把失败写进回执而不是抛错，调用方要按同一套分类处理这两种入口。 */
export function failureFromReceipt(
    receipt: MutationReceipt
): MofangSDKError | null {
    if (receipt.status !== 'failed') return null
    const code = receipt.errorCode || UNKNOWN_CODE
    return new MofangSDKError(receipt.errorMessage || code, {
        kind: classifyErrorCode(code),
        code,
        // 服务端已经受理并判定失败：重发同一个请求只会得到同样的结论。
        retryable: false,
        requestId: receipt.requestId,
        resourceRevision: receipt.resourceRevision
    })
}

/**
 * 传输层抛出的值统一收窄成 MofangSDKError。
 *
 * 传输层自己抛 MofangSDKError 时保留它的分类：只有实现方知道 HTTP 状态码，
 * 也由它决定"重发是否有意义"（例如 409 撞修订不该重发）。其他异常按结果未知处理，
 * 因为网络中断、超时都可能发生在服务端已经写入之后。
 */
export function toMofangSDKError(cause: unknown): MofangSDKError {
    if (cause instanceof MofangSDKError) return cause
    const message = cause instanceof Error ? cause.message : String(cause)
    return new MofangSDKError(message, {
        kind: 'transport',
        code: TRANSPORT_CODE,
        retryable: true
    })
}

/** 授权失效须清理受保护缓存，不能按普通网络故障继续使用旧权限。 */
export function isNodeAuthorizationError(error: MofangSDKError): boolean {
    return (
        error.httpStatus === 401 ||
        error.httpStatus === 403 ||
        [
            'http_401',
            'http_403',
            'unauthorized',
            'unauthenticated',
            'permission_denied',
            'scope_changed',
            'token_expired'
        ].includes(error.code)
    )
}
