type Lifecycle = { pending: Set<AbortController>; subscribers: number }
const owners = new WeakMap<object, Map<string, Lifecycle>>()

/** 同一个 SDK/目标的普通 React 重渲染不取消在途动作；卸载或真正换绑才取消。 */
export function hostLifecycle(owner: object, key: string) {
    const entries = owners.get(owner) ?? new Map<string, Lifecycle>()
    owners.set(owner, entries)
    const lifecycle = entries.get(key) ?? {
        pending: new Set<AbortController>(),
        subscribers: 0
    }
    entries.set(key, lifecycle)
    return {
        pending: lifecycle.pending,
        retain() {
            lifecycle.subscribers++
            return () => {
                lifecycle.subscribers--
                queueMicrotask(() => {
                    if (lifecycle.subscribers) return
                    for (const controller of lifecycle.pending)
                        controller.abort()
                    lifecycle.pending.clear()
                    if (entries.get(key) === lifecycle) entries.delete(key)
                })
            }
        }
    }
}
