import type { Condition, RuntimeSnapshot, ValueRef } from './contracts'
export const isObject = (value: unknown): value is Record<string, unknown> =>
    !!value && typeof value === 'object' && !Array.isArray(value)
const unsafe = new Set(['__proto__', 'prototype', 'constructor'])
export const safeKey = (key: string) => !!key && !unsafe.has(key)
/** 这些位置保存业务数据，不把其中恰好同名的键当成逻辑引用。 */
export const isLiteralProperty = (
    owner: Record<string, unknown>,
    key: string
) =>
    ((key === 'rows' || key === 'selectedKeys') &&
        'tableId' in owner &&
        'columns' in owner) ||
    (key === 'data' &&
        typeof owner.kind === 'string' &&
        'operation' in owner) ||
    (key === 'pageVariables' && 'logicVersion' in owner) ||
    ((key === 'defaultValue' || key === 'options') &&
        ['string', 'number', 'boolean', 'object', 'array', 'any'].includes(
            String(owner.type)
        )) ||
    (key === 'defaults' && owner.type === 'dialog.open') ||
    (key === 'fallback' && typeof owner.from === 'string') ||
    (key === 'successValue' &&
        ('successPath' in owner || 'errorPath' in owner || 'path' in owner)) ||
    (key === 'ignore' && 'path' in owner && 'value' in owner)
export const optionBoolean = (value: unknown): boolean =>
    value === true || value === 'true' || value === 1
export const resolvePath = (value: unknown, path: string[] = []) =>
    path.reduce<unknown>(
        (current, key) =>
            safeKey(key) &&
            (isObject(current) || Array.isArray(current)) &&
            Object.prototype.hasOwnProperty.call(current, key)
                ? (current as Record<string, unknown>)[key]
                : undefined,
        value
    )
export function resolveRef(ref: ValueRef, snapshot: RuntimeSnapshot): unknown {
    let result: unknown
    if (ref.from === 'constant') result = ref.value
    else if (ref.from === 'object')
        result = Object.fromEntries(
            Object.entries(ref.entries).map(([key, value]) => {
                if (!safeKey(key)) throw new Error('禁止原型链键')
                return [key, resolveRef(value, snapshot)]
            })
        )
    else if (ref.from === 'array')
        result = ref.items.map((value) => resolveRef(value, snapshot))
    else if (ref.from === 'form') {
        const formId = ref.formId ?? snapshot.scope?.formId
        const form = snapshot.forms?.[formId ?? 'main']
        result = resolvePath(
            form ?? (formId && snapshot.forms ? undefined : snapshot.form),
            ref.path
        )
    } else if (ref.from === 'source') {
        const state = snapshot.sources[ref.sourceId]
        result = ['data', 'status', 'error'].includes(ref.path?.[0] ?? '')
            ? resolvePath(state, ref.path)
            : resolvePath(state?.data, ref.path)
    } else if (ref.from === 'table')
        result = resolvePath(
            snapshot.tables[ref.tableId || snapshot.scope?.tableId || ''],
            ref.path
        )
    else if (ref.from === 'dialog') {
        const dialog = snapshot.scope?.dialogId
            ? [...(snapshot.dialogStack ?? []), snapshot.dialog]
                  .reverse()
                  .find((value) => value.targetId === snapshot.scope?.dialogId)
            : snapshot.dialog
        result = resolvePath(dialog, ref.path)
    } else result = resolvePath(snapshot[ref.from], ref.path)
    if (result === undefined) result = ref.fallback
    if (
        result !== undefined &&
        ref.valueType &&
        ref.valueType !== 'any' &&
        (ref.valueType === 'array'
            ? !Array.isArray(result)
            : ref.valueType === 'null'
              ? result !== null
              : ref.valueType === 'object'
                ? !isObject(result)
                : typeof result !== ref.valueType)
    )
        throw new Error(`绑定类型不匹配，需要 ${ref.valueType}`)
    return result
}
export function matches(c: Condition, s: RuntimeSnapshot): boolean {
    if (c.operator === 'all' || c.operator === 'any')
        return c.operator === 'all'
            ? c.conditions.every((condition) => matches(condition, s))
            : c.conditions.some((condition) => matches(condition, s))
    if (c.operator === 'not') return !matches(c.condition, s)
    if (!('left' in c)) return false
    const left = resolveRef(c.left, s),
        right = c.right ? resolveRef(c.right, s) : undefined
    switch (c.operator) {
        case 'equals':
            return JSON.stringify(left) === JSON.stringify(right)
        case 'notEquals':
            return JSON.stringify(left) !== JSON.stringify(right)
        case 'contains':
            return Array.isArray(left)
                ? left.includes(right)
                : typeof left === 'string' &&
                      typeof right === 'string' &&
                      left.includes(right)
        case 'empty':
        case 'notEmpty': {
            const empty =
                left == null ||
                left === '' ||
                (Array.isArray(left) && !left.length)
            return c.operator === 'empty' ? empty : !empty
        }
        case 'gt':
            return (
                typeof left === 'number' &&
                typeof right === 'number' &&
                left > right
            )
        case 'lt':
            return (
                typeof left === 'number' &&
                typeof right === 'number' &&
                left < right
            )
    }
}
export const clone = <T>(value: T): T =>
    value === undefined ? value : (JSON.parse(JSON.stringify(value)) as T)
export const uniqueId = () =>
    `lc-${Date.now().toString(36)}-${Array.from(crypto.getRandomValues(new Uint32Array(2)), (n) => n.toString(36)).join('')}`

export class StaleExecutionError extends Error {}
export const abortable = <T>(
    promise: Promise<T>,
    signal: AbortSignal,
    message: string
): Promise<T> =>
    new Promise((resolve, reject) => {
        const abort = () => reject(new StaleExecutionError(message))
        if (signal.aborted) return abort()
        signal.addEventListener('abort', abort, { once: true })
        promise
            .then(resolve, reject)
            .finally(() => signal.removeEventListener('abort', abort))
    })
export const cancelled = (error: unknown) =>
    error instanceof StaleExecutionError ||
    (error instanceof Error && error.name === 'AbortError')
