import type { MofangSDK } from '../core/runtime-types'
import { MofangSDKError } from '../core/sdk-error'
import { WORKFLOW_SDK_METHODS, WORKFLOW_SDK_VERSION } from './catalog'
import type { WorkflowSdkService, WorkflowSdkServiceOptions } from './types'

const services = new WeakMap<MofangSDK, Map<string, WorkflowSdkService>>()

/** 只从公开目录建立门面，不遍历 transport、私有 store 或原型。同步返回值保持同步。 */
export function createWorkflowSdkService(
    options: WorkflowSdkServiceOptions
): WorkflowSdkService {
    const { sdk } = options
    const target = Object.freeze({ ...options.target })
    const key = JSON.stringify([target, Boolean(options.readOnly)])
    const cached = services.get(sdk)?.get(key)
    if (cached) return cached
    const value: Record<string, unknown> = Object.create(null)
    for (const method of WORKFLOW_SDK_METHODS) {
        const parts = method.path.split('.')
        let facade = value
        for (const part of parts.slice(0, -1)) {
            facade[part] ??= Object.create(null)
            facade = facade[part] as Record<string, unknown>
        }
        facade[parts.at(-1)!] = (...args: unknown[]) => {
            const invoke = () => {
                if (
                    method.effect === 'write' &&
                    (options.readOnly || target.view === 'history')
                ) {
                    throw new MofangSDKError(
                        '当前面板为只读，不能执行 SDK 写入',
                        {
                            kind: 'rejected',
                            code: 'readonly_view',
                            retryable: false
                        }
                    )
                }
                let owner: unknown = sdk
                for (const part of parts.slice(0, -1))
                    owner = (owner as Record<string, unknown>)?.[part]
                const fn = (owner as Record<string, unknown>)?.[parts.at(-1)!]
                if (typeof fn !== 'function')
                    throw new MofangSDKError(`当前 SDK 未提供 ${method.path}`, {
                        kind: 'rejected',
                        code: 'operation_unavailable',
                        retryable: false
                    })
                return Reflect.apply(fn, owner, args)
            }
            if (method.kind !== 'async') return invoke()
            try {
                return Promise.resolve(invoke())
            } catch (error) {
                return Promise.reject(error)
            }
        }
    }
    const service = {
        version: WORKFLOW_SDK_VERSION,
        actionPrefix: 'sdk.',
        methods: WORKFLOW_SDK_METHODS,
        value: value as unknown as MofangSDK,
        subscribe: sdk.subscribe.bind(sdk),
        target
    }
    const entries = services.get(sdk) ?? new Map<string, WorkflowSdkService>()
    if (entries.size >= 64) entries.delete(entries.keys().next().value!)
    entries.set(key, service)
    services.set(sdk, entries)
    return service
}
